import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2023-01-05","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-01-05","date":"2023-01-05T00:00:00.000Z","updated":"2023-01-07T00:00:00.000Z","tags":["Ceph","Performance Testing","RocksDB","Distributed Storage","Database Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-01-05.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-01-05.md","lastUpdated":1780460162000}'),o={name:"posts/2023/Ceph_Performance_Meeting_2023-01-05.md"};function r(n,e,s,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>会议主持人：Mark</li><li>参会人员：Corey</li></ul><h4 id="会议主要议题" tabindex="-1">会议主要议题 <a class="header-anchor" href="#会议主要议题" aria-label="Permalink to &quot;会议主要议题&quot;">​</a></h4><ol><li><p><strong>Pull Requests (PRs) 更新</strong></p><ul><li>由于Ether pad服务中断，会议中未详细审查新的PRs。</li><li>讨论了关于m-clock工作的更新PR，意在增加一个高优先级队列。</li><li>Corey的PR收到评论，需进一步跟进。</li><li>两个PR已关闭，包括一个修复race condition的PR。</li></ul></li><li><p><strong>Corey的工作更新</strong></p><ul><li>Corey介绍了在假期前通过取消backfills和手动压缩数据稳定系统的经验。</li><li>正在考虑升级和测试新的调整设置，特别是关于删除操作的优化。</li><li>正在测试RocksDB版本7.8.3，特别是range delete的新特性。</li></ul></li><li><p><strong>RocksDB更新</strong></p><ul><li>讨论了RocksDB 7.8.3的新特性，特别是range delete的迭代优化。</li><li>计划尽快将新版本的RocksDB纳入测试。</li></ul></li><li><p><strong>数据库性能问题</strong></p><ul><li>讨论了数据库溢出到硬盘的问题，导致compaction过程耗时过长。</li><li>计划继续研究短期解决方案。</li></ul></li><li><p><strong>其他议题</strong></p><ul><li>讨论了Adam正在进行的优化RBD mirroring的共享blob管理的工作。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>尽快测试RocksDB 7.8.3的新特性，并评估其应用效果。</li><li>继续研究数据库溢出到硬盘的问题，并寻找短期解决方案。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Corey将继续测试RocksDB 7.8.3，并评估其对memtable和SSD文件的影响。</li><li>一旦实验室的VPN恢复，将尽快进行RocksDB的升级测试。</li><li>继续跟进Adam的工作进展，特别是关于优化blob管理的改进。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在感谢和告别中结束，计划下周再次会议。</li></ul><p><strong>备注</strong>：会议中提到的技术术语和产品名称如“m-clock”、“RocksDB”、“PR”等，保留原文以确保专业性和准确性。</p>',12)])])}const _=l(o,[["render",r]]);export{p as __pageData,_ as default};
